for t in di_topics:
    questions.append({
        "question": t[1],
        "options": t[2],
        "answer_index": t[3],
        "topic": t[0],
        "category": "Data Interpretation",
        "difficulty": "hard",
        "explanation": t[4]
    })

print(f"Total questions compiled: {len(questions)}")
category_counts = {}
for q in questions:
    c = q['category']
    category_counts[c] = category_counts.get(c, 0) + 1

for c, count in category_counts.items():
    print(f"  {c}: {count} questions")

# Write directly to sample_questions.json
target_file = os.path.join(os.path.dirname(__file__), '..', 'database', 'sample_questions.json')
with open(target_file, 'w', encoding='utf-8') as f:
    json.dump(questions, f, indent=2, ensure_ascii=False)

print(f"Successfully saved {len(questions)} questions to {target_file}")
